import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load and apply texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene placement
  const [px, py, pz] = config.scenePosition;
  const [rx, ry, rz] = config.sceneRotation;
  const [sx, sy, sz] = config.sceneScale;

  group.position.set(px, py, pz);
  group.rotation.set(rx, ry, rz);
  group.scale.set(sx, sy, sz);

  // Manage animation timelines
  let hoverTl = null;
  let clickTl = null;
  let badgeMesh = null;

  // Event handlers
  const handlers = {};

  // Hover animation: rise-in preset (0.15 scene units, power3.out, 0.7s)
  handlers.onHover = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(group.position, {
      y: py + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  handlers.onHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(group.position, {
      y: py,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  // Click animation: press-down (scale 0.97, back.out, 0.12s)
  handlers.onClick = () => {
    if (clickTl) clickTl.kill();
    clickTl = gsap.timeline();

    clickTl.to(group.scale, {
      x: sx * 0.97,
      y: sy * 0.97,
      duration: 0.12,
      ease: 'back.out',
    }).to(group.scale, {
      x: sx,
      y: sy,
      duration: 0.12,
      ease: 'back.out',
    });
  };

  // Stock badge: bind to inStock data (trpc.inventory.status.inStock)
  handlers.updateStockBadge = (inStock) => {
    if (!badgeMesh) {
      const badgeGeo = new THREE.PlaneGeometry(0.15, 0.15);
      const badgeMat = new THREE.MeshBasicMaterial({
        color: new THREE.Color(inStock ? '#ff2a38' : '#999999'),
      });
      badgeMesh = new THREE.Mesh(badgeGeo, badgeMat);
      badgeMesh.position.set(0.425, 0.425, 0.01);
      group.add(badgeMesh);
    } else {
      badgeMesh.material.color.set(inStock ? '#ff2a38' : '#999999');
    }
  };

  // Cleanup: dispose resources and kill animations
  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (clickTl) clickTl.kill();
    geometry.dispose();
    material.dispose();
    texture.dispose();
    if (badgeMesh) {
      badgeMesh.geometry.dispose();
      badgeMesh.material.dispose();
    }
  };

  group.userData.handlers = handlers;

  return group;
}
